import type {StudyQuestion} from './questionTypes';
import {deliveryOperationsSources,type DeliveryOperationsSource} from './authoredQuestionsDeliveryOperations.sources';
type Choice=[text:string,explanation:string];
function q(skill:string,variant:'a'|'b',chapter:string,services:string[],sources:DeliveryOperationsSource[],prompt:string,choices:Choice[],correct:number|number[],snippet?:string):StudyQuestion {
 const answers=Array.isArray(correct)?correct:[correct];
 return {id:`authored-c03-${skill.replaceAll('.','-')}-${variant}`,revision:1,examVersions:['DVA-C03'],skillRefs:[`DVA-C03:${skill}`],chapterIds:[chapter],serviceIds:services,kind:answers.length>1?'multiple-response':'single-choice',prompt,options:choices.map(([text,explanation],index)=>({id:String.fromCharCode(97+index),text,explanation})),correctOptionIds:answers.map(index=>String.fromCharCode(97+index)),explanation:answers.map(index=>choices[index][1]).join(' '),sourceUrls:sources.map(key=>deliveryOperationsSources[key][0]),...(snippet?{snippet}:{}),origin:'authored'};
}

